<template><view class="free-seal-editor ui-v2" :style="insets">
 <view class="free-head"><AppButton variant="text" @click="$emit('cancel')">取消</AppButton><text>摆放这枚印记</text><AppButton variant="text" @click="finish">完成</AppButton></view>
 <view class="free-stage"><view class="free-paper" :style="paperStyle"><image class="free-base" :src="pages[pageIndex]" mode="scaleToFill"/><view class="free-clip"><image :src="sealUrl" class="free-ink" :style="sealStyle" mode="scaleToFill"/></view><view class="free-selection" :data-x="value.centerX" :data-y="value.centerY" :data-angle="value.rotationDeg" :data-width="value.widthRatio" :style="sealStyle" @touchstart.stop="start($event,'move')" @touchmove.stop.prevent="move" @touchend.stop="end" @touchcancel.stop="cancelGesture" @mousedown.stop.prevent="mouseStart($event,'move')"><view class="free-handle" @touchstart.stop="start($event,'handle')" @mousedown.stop.prevent="mouseStart($event,'handle')"/></view></view></view>
 <text class="free-hint free-placement-hint" :class="{'free-overlap-hint':coversText}" role="status">{{coversText?'印记覆盖了部分文字，可保留，也可继续调整。':'拖动印记 · 拖角点旋转缩放 · 可盖在文字上'}}</text>
 <view class="free-controls"><view v-if="pages.length>1" class="free-page-picker"><AppButton variant="text" :disabled="pageIndex===0" @click="changePage(-1)">上一页</AppButton><text>{{pageIndex+1}} / {{pages.length}} · 只盖此页</text><AppButton variant="text" :disabled="pageIndex===pages.length-1" @click="changePage(1)">下一页</AppButton></view><view class="free-slider"><text>大小</text><slider :value="Math.round(value.widthRatio*100)" min="6" max="38" activeColor="#53614C" @changing="slide('widthRatio',$event.detail.value/100)" @change="slideEnd('widthRatio',$event.detail.value/100)"/><text>{{Math.round(value.widthRatio*100)}}%</text></view><view class="free-slider"><text>旋转</text><slider :value="Math.round(value.rotationDeg)" min="-180" max="180" activeColor="#53614C" @changing="slide('rotationDeg',$event.detail.value)" @change="slideEnd('rotationDeg',$event.detail.value)"/><text>{{Math.round(value.rotationDeg)}}°</text></view><view class="free-actions"><AppButton :disabled="!history.length" @click="undo">撤销</AppButton><AppButton @click="reset">重置 / 找回</AppButton></view><text class="free-hint">纸外部分会裁切，完成后查看净图。</text></view>
</view></template>
<script>
import {normalizeSealTransform,moveSeal,turnSeal,pinchSeal,paperPoint,sealOverlapsText} from '../common/seal-transform.js';
import {creativeInsets} from '../common/creative-insets.js';
export default{props:{pages:Array,sealUrl:String,initial:Object,pageSizes:Array,textBounds:Array},emits:['cancel','complete'],data(){return{insets:creativeInsets(),value:normalizeSealTransform(this.initial),history:[],gesture:null,sliderBase:null,rect:null,paperWidth:0,paperHeight:0};},computed:{coversText(){return sealOverlapsText(this.pageSizes[this.pageIndex],this.value,this.textBounds?.[this.pageIndex]||[]);},pageIndex(){return this.value.pageIndex;},ratio(){const p=this.pageSizes[this.pageIndex];return p.height/p.width;},paperStyle(){return{width:this.paperWidth+'px',height:this.paperHeight+'px'};},sealStyle(){return{left:(this.value.centerX*100)+'%',top:(this.value.centerY*100)+'%',width:(this.value.widthRatio*this.paperWidth)+'px',height:(this.value.widthRatio*this.paperWidth)+'px',transform:'translate(-50%,-50%) rotate('+this.value.rotationDeg+'deg)'};}},mounted(){this.measure();
// #ifdef H5
window.addEventListener('resize',this.measure);
// #endif
},beforeUnmount(){this.removeMouse();
// #ifdef H5
window.removeEventListener('resize',this.measure);
// #endif
},methods:{measure(){this.$nextTick(()=>uni.createSelectorQuery().in(this).select('.free-stage').boundingClientRect(r=>{if(!r)return;this.paperWidth=Math.min(r.width-32,(r.height-16)/this.ratio);this.paperHeight=this.paperWidth*this.ratio;this.$nextTick(()=>uni.createSelectorQuery().in(this).select('.free-paper').boundingClientRect(p=>{this.rect=p;}).exec());}).exec());},points(e){return Array.from(e.touches||[e]).map(p=>paperPoint(p,this.rect));},start(e,kind){if(!this.rect)return;const points=this.points(e);if(!this.gesture)this.gesture={original:{...this.value}};this.gesture={...this.gesture,kind:points.length>1?'pinch':kind,base:{...this.value},points};},move(e){if(!this.gesture)return;const p=this.points(e),g=this.gesture;if(p.length!==g.points.length){this.start(e,p.length>1?'pinch':'move');return;}this.value=g.kind==='pinch'?pinchSeal(g.base,g.points[0],g.points[1],p[0],p[1],this.ratio):g.kind==='handle'?turnSeal(g.base,g.points[0],p[0],this.ratio):moveSeal(g.base,g.points[0],p[0]);},end(e){if(!this.gesture)return;if(e?.touches?.length){this.start(e,'move');return;}this.history.push(this.gesture.original);this.gesture=null;this.removeMouse();},cancelGesture(){if(this.gesture)this.value=this.gesture.original;this.gesture=null;this.removeMouse();},mouseStart(e,k){
// #ifdef H5
this.start(e,k);this.mm=e=>this.move(e);this.mu=e=>this.end(e);window.addEventListener('mousemove',this.mm);window.addEventListener('mouseup',this.mu);window.addEventListener('blur',this.cancelGesture);
// #endif
},removeMouse(){
// #ifdef H5
window.removeEventListener('mousemove',this.mm);window.removeEventListener('mouseup',this.mu);window.removeEventListener('blur',this.cancelGesture);
// #endif
},slide(k,v){if(!this.sliderBase)this.sliderBase={...this.value};this.value=normalizeSealTransform({...this.value,[k]:v});},slideEnd(k,v){this.slide(k,v);this.history.push(this.sliderBase);this.sliderBase=null;},undo(){this.cancelGesture();if(this.history.length)this.value=this.history.pop();this.measure();},reset(){this.history.push({...this.value});this.value=normalizeSealTransform({...this.initial,pageIndex:this.pageIndex});this.measure();},changePage(n){this.history.push({...this.value});this.value={...this.value,pageIndex:this.pageIndex+n};this.measure();},finish(){this.cancelGesture();this.$emit('complete',{...this.value});}}};
</script>
<style scoped>
.free-seal-editor{position:fixed;inset:0;z-index:110;display:flex;flex-direction:column;background:var(--ui-page);padding-top:var(--creative-top);padding-bottom:var(--creative-bottom);color:var(--ui-ink)}.free-head{display:flex;align-items:center;justify-content:space-between;padding:4px 12px;font-size:18px}.free-stage{flex:1;min-height:150px;display:flex;align-items:center;justify-content:center;background:var(--ui-group)}.free-paper{position:relative;box-shadow:var(--ui-float-shadow);background:var(--ui-paper)}.free-base,.free-clip{position:absolute;inset:0;width:100%;height:100%}.free-clip{overflow:hidden;pointer-events:none}.free-ink,.free-selection{position:absolute;transform-origin:center}.free-selection{border:1px solid var(--ui-action);touch-action:none;cursor:move;box-sizing:border-box;min-width:24px;min-height:24px}.free-handle{position:absolute;bottom:-24px;right:-24px;width:32px;height:32px;box-sizing:border-box;border-radius:50%;border:3px solid var(--ui-paper);box-shadow:0 0 0 1px var(--ui-action);background:var(--ui-action);cursor:nwse-resize}.free-hint{display:block;text-align:center;font-size:12px;color:var(--ui-muted);line-height:20px;padding:8px}.free-placement-hint{height:56px;box-sizing:border-box;flex-shrink:0;display:flex;align-items:center;justify-content:center}.free-overlap-hint{color:var(--ui-ink)}.free-controls{padding:0 var(--ui-gutter);flex-shrink:0}.free-slider{display:flex;align-items:center;font-size:13px;gap:8px;min-height:44px}.free-slider slider{flex:1}.free-slider>text:last-child{width:40px;text-align:right}.free-actions{display:flex;gap:12px}.free-actions :deep(.ui-button){flex:1}.free-page-picker{display:flex;align-items:center;justify-content:space-between;font-size:12px}
</style>
